const b = $json.body || $json;
const to = String(b.whatsapp || b.to || '').trim();
const marca = String(b.marca || b.cliente || '').trim();
const landingUrl = String(b.landingUrl || '').trim();
const paquete = String(b.paquete || 'presencia').trim();
const texto = [
  `Listo${marca ? ' — ' + marca : ''}: tu presencia digital quedó armada.`,
  landingUrl ? `Web: ${landingUrl}` : 'Web: (pegar URL)',
  'Google Business: revisá nombre, horarios y link a la web.',
  paquete === 'completo' ? 'Wasap task: activado / en configuración.' : '',
  'Si querés cambios chicos, podemos sumar mantenimiento mensual.'
].filter(Boolean).join('\n');
if (!to) {
  return [{ json: { ok: false, error: 'falta whatsapp', texto } }];
}
return [{ json: {
  ok: true,
  sistema: '07-presencia-digital',
  etapa: 'entrega',
  to,
  texto,
  status: 'draft_ready',
  todo: 'TODO_CREDENCIAL: enviar Wasap',
  at: new Date().toISOString()
}}];
